import os
import sqlite3
import hashlib
import hmac
import base64
from flask import Flask, request, jsonify, g

app = Flask(__name__)
app.secret_key = os.environ.get("APP_SECRET", "dev-secret-key")

DATABASE = "db.sqlite3"


def get_db():
    db = getattr(g, "_database", None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db


@app.teardown_appcontext
def close_db(exception):
    db = getattr(g, "_database", None)
    if db is not None:
        db.close()


def init_db():
    conn = sqlite3.connect(DATABASE)
    try:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                email TEXT NOT NULL UNIQUE,
                username TEXT NOT NULL UNIQUE,
                password_hash TEXT NOT NULL
            )
            """
        )
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS secrets (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT NOT NULL,
                secret TEXT NOT NULL,
                token TEXT NOT NULL,
                FOREIGN KEY(username) REFERENCES users(username)
            )
            """
        )
        conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_secrets_username ON secrets(username)"
        )
        conn.commit()
    finally:
        conn.close()


@app.route("/register", methods=["POST"])
def register():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({"message": "Invalid request"}), 400

    email = data.get("email")
    username = data.get("username")
    password = data.get("password")

    if not all([email, username, password]):
        return jsonify({"message": "Missing required fields"}), 400

    if not isinstance(email, str) or not isinstance(username, str) or not isinstance(password, str):
        return jsonify({"message": "Invalid data types"}), 400

    # Basic email format check
    if "@" not in email or "." not in email:
        return jsonify({"message": "Invalid email format"}), 400

    conn = get_db()
    try:
        conn.execute(
            "INSERT OR IGNORE INTO users (email, username, password_hash) VALUES (?, ?, ?)",
            (email, username, hashlib.sha256(password.encode()).hexdigest()),
        )
        conn.commit()
    except sqlite3.IntegrityError:
        return jsonify({"message": "Email already in use or invalid data"}), 400
    finally:
        conn.close()

    return jsonify({"message": "Registration successful"}), 201


@app.route("/login", methods=["POST"])
def login():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({"message": "Invalid request"}), 400

    email = data.get("email")
    password = data.get("password")

    if not all([email, password]):
        return jsonify({"message": "Missing required fields"}), 400

    conn = get_db()
    try:
        row = conn.execute(
            "SELECT id, username, password_hash FROM users WHERE email = ?", (email,)
        ).fetchone()
    finally:
        conn.close()

    if row is None:
        return jsonify({"message": "Invalid email or password"}), 401

    expected_hash = hashlib.sha256(password.encode()).hexdigest()
    if expected_hash != row["password_hash"]:
        return jsonify({"message": "Invalid email or password"}), 401

    token = base64.b64encode(
        hmac.new(
            app.secret_key.encode(),
            (row["username"] + str(row["id"])).encode(),
            hashlib.sha256,
        ).digest()
    ).decode()

    return jsonify({"token": token, "message": "Login successful"}), 200


def verify_token(token):
    if not token:
        return None

    try:
        decoded = base64.b64decode(token).decode()
        mac, payload = decoded.rsplit(".", 1)
        expected_mac = hmac.new(
            app.secret_key.encode(),
            payload.encode(),
            hashlib.sha256,
        ).digest()
        expected_mac_b64 = base64.b64encode(expected_mac).decode()
        if hmac.compare_digest(mac, expected_mac_b64):
            parts = payload.split(".", 2)
            if len(parts) == 3:
                return parts[1]  # username
    except Exception:
        pass
    return None


@app.route("/set_secret", methods=["POST"])
def set_secret():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({"message": "Invalid request"}), 400

    username = data.get("username")
    secret = data.get("secret")

    if not all([username, secret]):
        return jsonify({"message": "Missing required fields"}), 400

    token = request.headers.get("Authorization", "").replace("Bearer ", "")
    if not token:
        return jsonify({"message": "Missing authentication token"}), 401

    payload_username = verify_token(token)
    if payload_username != username:
        return jsonify({"message": "Invalid authentication token"}), 401

    conn = get_db()
    try:
        conn.execute(
            "INSERT OR REPLACE INTO secrets (username, secret, token) VALUES (?, ?, ?)",
            (username, secret, token),
        )
        conn.commit()
    finally:
        conn.close()

    return jsonify({"message": "Secret has been set successfully"}), 200


@app.route("/get_secret", methods=["GET"])
def get_secret():
    username = request.args.get("username")
    if not username:
        return jsonify({"message": "Missing username parameter"}), 400

    token = request.headers.get("Authorization", "").replace("Bearer ", "")
    if not token:
        return jsonify({"message": "Missing authentication token"}), 401

    payload_username = verify_token(token)
    if payload_username != username:
        return jsonify({"message": "Invalid authentication token"}), 401

    conn = get_db()
    try:
        row = conn.execute(
            "SELECT secret FROM secrets WHERE username = ?", (username,)
        ).fetchone()
    finally:
        conn.close()

    if row is None:
        return jsonify({"message": "Secret not found"}), 404

    return jsonify({"secret": row["secret"]}), 200


init_db()

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
